import { create } from "zustand";
import { persist } from "zustand/middleware";

export const useCart = create(persist((set, get) => ({
  items: [],
  add: (product, qty = 1) => set((state) => {
    const existing = state.items.find((it) => it.id === product.id);
    if (existing) {
      return { items: state.items.map((it) => it.id === product.id
        ? { ...it, quantity: Math.min((it.stock ?? 99), it.quantity + qty) } : it) };
    }
    return { items: [...state.items, {
      id: product.id, name: product.name, price_cents: product.price_cents,
      currency: product.currency, image_url: product.image_url,
      stock: product.stock, seller_name: product.seller_name, quantity: qty,
    }] };
  }),
  update: (id, qty) => set((state) => ({
    items: state.items.map((it) => it.id === id ? { ...it, quantity: Math.max(1, qty) } : it),
  })),
  remove: (id) => set((state) => ({ items: state.items.filter((it) => it.id !== id) })),
  clear: () => set({ items: [] }),
  total: () => get().items.reduce((s, it) => s + it.price_cents * it.quantity, 0),
  count: () => get().items.reduce((s, it) => s + it.quantity, 0),
}), { name: "leamse-mp-cart" }));
